	if text == "" {
		var ok bool
		if text, ok = ocr.Tasks[*task]; !ok {
			log.Fatalf("unknown task %q; one of %s", *task, strings.Join(taskNames(), ", "))
		}
	}
	data, err := os.ReadFile(*image)
	must(err)
	img, _, err := pixels.Decode(data)
	must(err)

	dev, done := openDevice()
	defer done()
	o := ocr.DefaultOptions()
	o.MaxPatches = *maxPixels / (ocr.PatchSize * ocr.PatchSize)
	if o.MaxPatches < ocr.MaxPatches {
		o.MaxPatches = ocr.MaxPatches
	}
	start := time.Now()
	e, err := ocr.Load(dev, *model, o)
	must(err)
	defer e.Destroy()
	fmt.Fprintf(os.Stderr, "loaded   %v, %.2f GB on the device\n", time.Since(start).Round(time.Millisecond), float64(e.DeviceBytes())/1e9)

	if *pageMode {
		runPage(dev, e, img, *layoutModel)
		return
	}
	start = time.Now()
	res, err := e.Recognize(context.Background(), ocr.Request{
		Image: img, Prompt: text, MinPixels: *minPixels, MaxPixels: *maxPixels, MaxTokens: *maxTokens,
	})
	must(err)
	wall := time.Since(start)
	fmt.Println(res.Text)
	fmt.Fprintf(os.Stderr, "image    %dx%d -> %dx%d patches, %d prompt tokens\n", img.W, img.H, res.GridW, res.GridH, res.PromptTokens)
	fmt.Fprintf(os.Stderr, "time     process %v, tower %v, prefill %v, decode %v\n",
		res.Process.Round(time.Millisecond), res.Tower.Round(time.Millisecond),
		res.Prefill.Round(time.Millisecond), res.Decode.Round(time.Millisecond))
	fmt.Fprintf(os.Stderr, "tokens   %d (%s), %.2f ms a token, %.0f tok/s; %v in all\n", len(res.IDs), res.Finish,
		float64(res.Decode.Microseconds())/1e3/float64(len(res.IDs)),
		float64(len(res.IDs))/res.Decode.Seconds(), wall.Round(time.Millisecond))
}

func taskNames() []string {
	var out []string
	for k := range ocr.Tasks {
		out = append(out, k)
	}
	sort.Strings(out)
	return out
}

func openDevice() (*vk.Device, func()) {
	inst, err := vk.NewInstance("ocr")
	must(err)
	devices, err := inst.PhysicalDevices()
	must(err)
	if len(devices) == 0 {
		log.Fatal("no Vulkan devices")
	}
	phys := &devices[0]
	for i := range devices {
		if devices[i].DeviceID == strixHaloDeviceID {
			phys = &devices[i]
		}
	}
	qf, err := phys.ComputeQueueFamily()
	must(err)
	sgs, err := phys.SubgroupSizeControl()
	must(err)
	dev, err := vk.NewDevice(phys, qf, vk.DeviceFeatures{Float16: true, CoopMatrix: true, SubgroupSizeControl: sgs.Supported})
	must(err)
	return dev, func() { dev.Destroy(); inst.Destroy() }
}

func must(err error) {
	if err != nil {
		log.Fatal(err)
	}
}

// runPage parses img as a page and prints the markdown.
func runPage(dev *vk.Device, e *ocr.Engine, img *pixels.RGB, dir string) {
	start := time.Now()
	lm, err := layout.Load(dir)
	must(err)
	lg, err := layout.NewGPU(dev, lm)
	must(err)
	defer lg.Destroy()
	fmt.Fprintf(os.Stderr, "layout   %v\n", time.Since(start).Round(time.Millisecond))
	p := &page.Parser{
		Layout: func(px []float32) (*layout.Output, error) {
			out, _, err := lg.Forward(px, nil)
			return out, err
		},
		Recognize: e.Recognize,
	}
	start = time.Now()
	pg, err := p.Parse(context.Background(), img)
	must(err)
	fmt.Println(pg.Markdown)
	fmt.Fprintf(os.Stderr, "page     %dx%d: %d regions, %d blocks, %d recognitions\n", img.W, img.H, len(pg.Boxes), len(pg.Blocks), len(pg.Entries))
	fmt.Fprintf(os.Stderr, "time     layout %v, glue %v, recognition %v; %v in all\n",
		pg.Timings.Layout.Round(time.Millisecond), pg.Timings.Glue.Round(time.Millisecond),
		pg.Timings.Recognition.Round(time.Millisecond), time.Since(start).Round(time.Millisecond))
}

// Page is one parsed page and how it got there.
type Page struct {
	Width, Height int
	// Boxes are the layout regions after PaddleX's post-processing.
	Boxes   []Box
	Blocks  []Block
	Entries []Entry
	// Texts are the raw recognitions, one an entry.
	Texts    []string
	Results  []Result
	Markdown string
	Timings  Timings
}

// Timings is where a page's time went.
type Timings struct {
	Layout, Glue, Recognition time.Duration
}

// Parser runs pages: Layout is PP-DocLayoutV3 over the preprocessed page
// (the device trunk's or the CPU oracle's Forward), Recognize the
// element-level engine.
type Parser struct {
	Layout    func(pixels []float32) (*layout.Output, error)
	Recognize func(ctx context.Context, req ocr.Request) (*ocr.Result, error)
}

// Parse runs one page.
func (p *Parser) Parse(ctx context.Context, img *pixels.RGB) (*Page, error) {
	pg := &Page{Width: img.W, Height: img.H}
	t0 := time.Now()
	out, err := p.Layout(layout.Preprocess(img))
	if err != nil {
		return nil, err
	}
	pg.Boxes = LayoutPost(out.Detect(img.W, img.H, layoutThreshold), img.W, img.H)
	pg.Timings.Layout = time.Since(t0)

	t0 = time.Now()
	var figures []Box
	for _, b := range pg.Boxes {
		if figureLabels[b.Label] {
			figures = append(figures, b)
		}
	}
	for _, b := range filterOverlap(pg.Boxes) {
		pg.Blocks = append(pg.Blocks, Block{Label: b.Label, Box: b.Coord, Img: crop(img, b.Coord), GroupID: -1})
	}
	nonMerge := map[string]bool{"table": true}
	for l := range imageLabels {
		nonMerge[l] = true
	}
	pg.Blocks = mergeBlocks(pg.Blocks, nonMerge)
	ents, drop, err := entries(pg.Blocks, figures)
	if err != nil {
		return nil, err
	}
	pg.Entries = ents
	pg.Timings.Glue = time.Since(t0)

	t0 = time.Now()
	for _, e := range ents {
		res, err := p.Recognize(ctx, ocr.Request{Image: e.Img, Prompt: e.Prompt, MinPixels: e.MinPixels, MaxPixels: e.MaxPixels, MaxTokens: maxNewTokens})
		if err != nil {
			return nil, fmt.Errorf("page: block %d (%s): %w", e.Block, pg.Blocks[e.Block].Label, err)
		}
		pg.Texts = append(pg.Texts, res.Text)
	}
	pg.Timings.Recognition = time.Since(t0)
	pg.Results = assemble(pg.Blocks, ents, pg.Texts, drop)
	pg.Markdown = Markdown(pg.Results, img.W)
	return pg, nil
}

