package pixels

import "math"

// ResizeCV2Cubic is OpenCV 4.10's cv2.resize(INTER_CUBIC) on an 8-bit RGB
// image (imgproc/src/resize.cpp, the generic path): Keys' cubic with
// A = -0.75, taps rounded to 11-bit fixed point, the horizontal pass in
// integers, the vertical pass in float32 as its SIMD kernel computes it
// (VResizeCubicVec_32s8u), edges replicated. PaddleX's Paddle engine
// resizes PP-DocLayoutV3's input with it (OCR.md O10).
func ResizeCV2Cubic(src *RGB, w, h int) *RGB {
	const cn = 3
	const coefScale = 1 << 11
	sw, sh := src.W, src.H
	scaleX := 1 / (float64(w) / float64(sw))
	scaleY := 1 / (float64(h) / float64(sh))

	width := w * cn
	xofs := make([]int, width)
	ialpha := make([]int32, width*4)
	xmin, xmax := 0, w
	var cbuf [4]float32
	for dx := 0; dx < w; dx++ {
		fx := float32((float64(dx)+0.5)*scaleX - 0.5)
		sx := int(math.Floor(float64(fx)))
		fx -= float32(sx)
		if sx < 1 {
			xmin = dx + 1
		}
		if sx+2 >= sw {
			xmax = min(xmax, dx)
		}
		for k := 0; k < cn; k++ {
			xofs[dx*cn+k] = sx*cn + k
		}
		cubicCV2(fx, &cbuf)
		for k := 0; k < 4; k++ {
			ialpha[dx*cn*4+k] = saturateShort(cbuf[k] * coefScale)
		}
		for k := 4; k < cn*4; k++ {
			ialpha[dx*cn*4+k] = ialpha[dx*cn*4+k-4]
		}
	}
	xmin *= cn
	xmax *= cn
	swidth := sw * cn

	hresize := func(row []uint8, out []int32) {
		for dx := 0; dx < width; dx++ {
			a := ialpha[dx*4 : dx*4+4]
			sx := xofs[dx]
			if dx >= xmin && dx < xmax {
				out[dx] = int32(row[sx-cn])*a[0] + int32(row[sx])*a[1] + int32(row[sx+cn])*a[2] + int32(row[sx+2*cn])*a[3]
				continue
			}
			var v int32
			for j := 0; j < 4; j++ {
				sxj := sx - cn + j*cn
				for sxj < 0 {
					sxj += cn
				}
				for sxj >= swidth {
					sxj -= cn
				}
				v += int32(row[sxj]) * a[j]
			}
			out[dx] = v
		}
	}

	dst := &RGB{W: w, H: h, Pix: make([]uint8, w*h*cn)}
	rows := [4][]int32{}
	rowOf := [4]int{-1, -1, -1, -1}
	for k := range rows {
		rows[k] = make([]int32, width)
	}
	const betaScale = float32(1) / (coefScale * coefScale)
	for dy := 0; dy < h; dy++ {
		fy := float32((float64(dy)+0.5)*scaleY - 0.5)
		sy := int(math.Floor(float64(fy)))
		fy -= float32(sy)
		cubicCV2(fy, &cbuf)
		var b [4]float32
		for k := 0; k < 4; k++ {
			b[k] = float32(saturateShort(cbuf[k]*coefScale)) * betaScale
		}
		var S [4][]int32
		for k := 0; k < 4; k++ {
			y := sy - 1 + k
			if y < 0 {
				y = 0
			} else if y >= sh {
				y = sh - 1
			}
			// rows[k] holds source row rowOf[k]; recompute only on a miss.
			found := -1
			for j := 0; j < 4; j++ {
				if rowOf[j] == y {
					found = j
					break
				}
			}
			if found < 0 {
				// take a slot no later tap of this output row needs
				for j := 0; j < 4; j++ {
					used := false
					for i := 0; i < k; i++ {
						if S[i] != nil && &S[i][0] == &rows[j][0] {
							used = true
						}
					}
					if !used && (rowOf[j] < sy-1 || rowOf[j] > sy+2 || rowOf[j] == -1) {
						found = j
						break
					}
				}
				if found < 0 {
					for j := 0; j < 4; j++ {
						used := false
						for i := 0; i < k; i++ {
							if &S[i][0] == &rows[j][0] {
								used = true
							}
						}
						if !used {
							found = j
							break
						}
					}
				}
				hresize(src.Pix[y*swidth:(y+1)*swidth], rows[found])
				rowOf[found] = y
			}
			S[k] = rows[found]
		}
		out := dst.Pix[dy*width : (dy+1)*width]
		for x := 0; x < width; x++ {
			// v_muladd(S0, b0, v_muladd(S1, b1, v_muladd(S2, b2, S3*b3))),
			// each product and sum rounded to float32.
			v := float32(S[3][x]) * b[3]
			v = float32(S[2][x])*b[2] + v
			v = float32(S[1][x])*b[1] + v
			v = float32(S[0][x])*b[0] + v
			r := math.RoundToEven(float64(v))
			switch {
			case r < 0:
				out[x] = 0
			case r > 255:
				out[x] = 255
			default:
				out[x] = uint8(r)
			}
		}
	}
	return dst
}

// cubicCV2 is resize.cpp interpolateCubic, in float32.
func cubicCV2(x float32, c *[4]float32) {
	const A = float32(-0.75)
	c[0] = ((A*(x+1)-5*A)*(x+1)+8*A)*(x+1) - 4*A
	c[1] = ((A+2)*x-(A+3))*x*x + 1
	c[2] = ((A+2)*(1-x)-(A+3))*(1-x)*(1-x) + 1
	c[3] = 1 - c[0] - c[1] - c[2]
}

// saturateShort is saturate_cast<short>(float): round half to even, clamp.
func saturateShort(v float32) int32 {
	r := math.RoundToEven(float64(v))
	if r < -32768 {
		return -32768
	}
	if r > 32767 {
		return 32767
	}
	return int32(r)
}

