				out[x] = 255
			default:
				out[x] = uint8(r)
			}
		}
	}
	return dst
}

// cubicCV2 is resize.cpp interpolateCubic, in float32.
func cubicCV2(x float32, c *[4]float32) {
	const A = float32(-0.75)
	c[0] = ((A*(x+1)-5*A)*(x+1)+8*A)*(x+1) - 4*A
	c[1] = ((A+2)*x-(A+3))*x*x + 1
	c[2] = ((A+2)*(1-x)-(A+3))*(1-x)*(1-x) + 1
	c[3] = 1 - c[0] - c[1] - c[2]
}

// saturateShort is saturate_cast<short>(float): round half to even, clamp.
func saturateShort(v float32) int32 {
	r := math.RoundToEven(float64(v))
	if r < -32768 {
		return -32768
	}
	if r > 32767 {
		return 32767
	}
	return int32(r)
}

