package layout

import (
	"encoding/json"
	"fmt"
	"os"
	"path/filepath"
	"testing"

	"strix-halo-vulkan/llm/pixels"
)

// TestResizeCV2 holds pixels.ResizeCV2Cubic to cv2.resize(INTER_CUBIC) at
// the layout input size, from the bytes cv2 decoded
// (reference/dump_cv2_resize.py): the Paddle engine's preprocessing.
func TestResizeCV2(t *testing.T) {
	dir := "../../reference/out/cv2_resize"
	raw, err := os.ReadFile(filepath.Join(dir, "cases.json"))
	if err != nil {
		t.Skipf("no reference (%v); run reference/dump_cv2_resize.py", err)
	}
	var cases []struct {
		Image string
		W, H  int
	}
	if err := json.Unmarshal(raw, &cases); err != nil {
		t.Fatal(err)
	}
	for k, c := range cases {
		in, err := os.ReadFile(filepath.Join(dir, fmt.Sprintf("%d.in.rgb", k)))
		if err != nil {
			t.Fatal(err)
		}
		want, err := os.ReadFile(filepath.Join(dir, fmt.Sprintf("%d.out.rgb", k)))
		if err != nil {
			t.Fatal(err)
		}
		got := pixels.ResizeCV2Cubic(&pixels.RGB{W: c.W, H: c.H, Pix: in}, InputSize, InputSize)
		n, worst := 0, 0
		for i := range want {
			if d := int(got.Pix[i]) - int(want[i]); d != 0 {
				n++
				worst = max(worst, d, -d)
			}
		}
		if n > 0 {
			t.Errorf("%s (%dx%d): %d of %d values differ, by up to %d", c.Image, c.W, c.H, n, len(want), worst)
		}
	}
	t.Logf("%d images", len(cases))
}
EOF
go test ./ocr/layout -run TestResizeCV2 -v 2>&1 | tail -22

